    /*
     * Display an agency information section only when
     * the corresponding value exists.
     */
    function setAgencySection(
        section,
        element,
        value
    ) {

        /*
         * Stop if the required DOM elements are unavailable.
         */
        if (
            !section ||
            !element
        ) {

            return;

        }


        /*
         * Normalize the value into a trimmed string.
         */
        const text =
            value
                ? String(value).trim()
                : '';


        /*
         * Show the section when information exists.
         */
        if (text) {

            /*
             * textContent treats database data as text
             * rather than executable HTML.
             */
            element.textContent =
                text;


            section.style.display =
                '';

        }


        /*
         * Otherwise hide the empty section.
         */
        else {

            element.textContent =
                '';

            section.style.display =
                'none';

        }

    }


    // =========================================================
    // CONTACT ITEM CREATION
    // =========================================================

    /*
     * Create a contact item using DOM APIs.
     *
     * This avoids injecting database-controlled contact
     * information directly into HTML.
     */
    function createContactItem(
        iconClass,
        label,
        value,
        href = null,
        isPrimary = false
    ) {

        /*
         * Ignore contacts without values.
         */
        if (!value) {

            return null;

        }


        /*
         * Create the contact row.
         */
        const row =
            document.createElement(
                'div'
            );


        row.className =
            'agency-contact-item';


        /*
         * Create the contact icon.
         */
        const icon =
            document.createElement(
                'i'
            );


        icon.className =
            `ph-light ${iconClass}`;


        icon.setAttribute(
            'aria-hidden',
            'true'
        );


        /*
         * Create the text container.
         */
        const content =
            document.createElement(
                'div'
            );


        content.className =
            'agency-contact-content';


        /*
         * Create the contact label.
         */
        const labelElement =
            document.createElement(
                'span'
            );


        labelElement.className =
            'agency-contact-label';


        labelElement.textContent =
            label;


        /*
         * Use an anchor only when a destination exists.
         */
        const valueElement =
            document.createElement(
                href
                    ? 'a'
                    : 'span'
            );


        valueElement.className =
            'agency-contact-value';


        /*
         * Safely display the actual contact value.
         */
        valueElement.textContent =
            value;


        /*
         * Configure the contact destination.
         */
        if (href) {

            valueElement.href =
                href;


            /*
             * External HTTP(S) destinations open safely
             * in a separate browsing context.
             */
            if (
                href.startsWith('https://') ||
                href.startsWith('http://')
            ) {

                valueElement.target =
                    '_blank';


                /*
                 * Prevent reverse-tabnabbing.
                 */
                valueElement.rel =
                    'noopener noreferrer';

            }

        }


        /*
         * Add label and value to the contact content.
         */
        content.appendChild(
            labelElement
        );


        content.appendChild(
            valueElement
        );


        /*
         * Add icon and content to the row.
         */
        row.appendChild(
            icon
        );


        row.appendChild(
            content
        );


        /*
         * Mark primary contacts visually.
         */
        if (isPrimary) {

            row.classList.add(
                'is-primary'
            );


            const primaryBadge =
                document.createElement(
                    'span'
                );


            primaryBadge.className =
                'agency-contact-primary';


            primaryBadge.textContent =
                'Primary';


            content.appendChild(
                primaryBadge
            );

        }


        /*
         * Return the finished DOM element.
         */
        return row;

    }


